# Generated by GitHub Copilot - Nov-17-2026
"""Deterministic ATS analysis: score, keyword match, missing skills, risks and weak points.

Runs fully offline (no AI required) so results are fast, repeatable and explainable.
"""
import re
from collections import Counter
from functools import lru_cache

from .lang_data import (ACTION_VERBS, EMAIL_RE, NUMBER_RE, PHONE_RE, SKILLS, STOPWORDS, WEAK_PATTERNS,
                        detect_language)
from .jd_utils import display_term, extract_company
from .resume_struct import parse_resume

# Common job-ad words that carry no skill signal.
GENERIC_JD_TERMS = set("""senior junior lead principal staff build design implement maintain improve drive operate
develop create manage support solutions scalable hands-on best practices responsibilities requirements
engineer engineering team teams environment candidate plus years strong deep solid proven equivalent
degree bachelor master related field ensure deliver across within""".split())

LATIN_TOKEN_RE = re.compile(r"[A-Za-zÀ-ÿñÑ][A-Za-zÀ-ÿñÑ0-9+#./-]*[A-Za-zÀ-ÿñÑ0-9+#]|[A-Za-z]{2,}")
CJK_RUN_RE = re.compile(r"[\u4e00-\u9fff]+")
SPECIAL_SYMBOL_RE = re.compile(r"[★☆✓✔✗✘☑◆◇■□►▶➤➢✦✧❖♦●○◉◎]")
YEAR_RE = re.compile(r"(?:19|20)\d{2}")
CORE_SECTIONS = ("experience", "education", "skills", "summary")


@lru_cache(maxsize=2048)
def _term_pattern(term: str) -> re.Pattern:
    """Whole-term regex that also works for terms such as c++, c#, node.js or .net."""
    if re.search(r"[\u4e00-\u9fff]", term):
        return re.compile(re.escape(term))
    return re.compile(r"(?<![\w+#])" + re.escape(term).replace(r"\ ", r"[\s-]+") + r"(?![\w+#])", re.IGNORECASE)


def _contains(text: str, term: str) -> bool:
    """True if `term` (or a simple inflection of it) appears in `text`."""
    if _term_pattern(term).search(text):
        return True
    if re.fullmatch(r"[a-z]{4,}", term):
        stem = re.sub(r"(ing|ed|es|s)$", "", term)
        if len(stem) >= 4 and re.search(r"(?<!\w)" + re.escape(stem) + r"\w{0,4}(?!\w)", text, re.IGNORECASE):
            return True
    return False


def extract_keywords(jd: str, lang: str, limit: int = 30) -> list[dict]:
    """Extract weighted keywords from a job description (known skills first, then salient terms)."""
    found: list[dict] = []
    for skill in SKILLS:
        if _term_pattern(skill).search(jd):
            found.append({"term": skill, "kind": "skill", "weight": 2})
    # drop shorter skills contained in longer matched ones (e.g. "ux" inside "ux design")
    found = [f for f in found if not any(f["term"] != o["term"] and f["term"] in o["term"].split() for o in found)]
    covered = {f["term"] for f in found}

    company_tokens = {t.lower() for t in extract_company(jd).split()}
    stop = STOPWORDS["en"] | STOPWORDS.get(lang, set()) | GENERIC_JD_TERMS | company_tokens
    counter: Counter[str] = Counter()
    tokens = [t.lower().strip(".-/") for t in LATIN_TOKEN_RE.findall(jd)]
    capitalised = {t.lower() for t in re.findall(r"(?<![.!?]\s)(?<!^)\b[A-Z][a-zA-Z0-9+#]{2,}", jd)}
    for t in tokens:
        if len(t) >= 3 and t not in stop and not t.isdigit():
            counter[t] += 2 if t in capitalised else 1
    for a, b in zip(tokens, tokens[1:]):
        if a not in stop and b not in stop and len(a) > 2 and len(b) > 2:
            counter[f"{a} {b}"] += 1
    if lang in ("hi", "ar"):
        for t in re.findall(r"[\u0900-\u097f\u0600-\u06ff]{2,}", jd):
            if t not in stop:
                counter[t] += 1
    if lang == "zh" or CJK_RUN_RE.search(jd):
        for run in CJK_RUN_RE.findall(jd):
            for n in (4, 3, 2):
                for i in range(len(run) - n + 1):
                    gram = run[i:i + n]
                    if not any(sw in gram for sw in STOPWORDS["zh"] if len(sw) >= 2):
                        counter[gram] += 1

    extras = []
    for term, count in counter.most_common():
        if count < 2 and not (term in capitalised and count >= 1 and " " not in term):
            continue
        if term in covered or any(term in c or c in term for c in covered):
            continue
        if any(term in e["term"] for e in extras):
            continue  # a longer phrase already captures this term
        extras.append({"term": term, "kind": "keyword", "weight": 1})
        if len(found) + len(extras) >= limit:
            break
    return (found + extras)[:limit]


def _word_count(text: str) -> int:
    """Approximate word count that also works for Chinese text."""
    return len(re.findall(r"\S+", re.sub(r"[\u4e00-\u9fff]", " ", text))) + int(
        len(re.findall(r"[\u4e00-\u9fff]", text)) / 1.8)


def _starts_with_action_verb(text: str, lang: str) -> bool:
    """True if a bullet opens with a strong action verb for the given language."""
    first = re.sub(r"[^\wÀ-ÿ]", "", (text.split() or [""])[0].lower())
    return first in ACTION_VERBS.get(lang, set())


def _collect_bullets(doc: dict) -> list[str]:
    """Achievement lines from experience-like sections (falls back to long text lines)."""
    bullets, fallback = [], []
    for sec in doc["sections"]:
        if sec["key"] in ("experience", "projects", "achievements", "other"):
            for item in sec["items"]:
                if item["type"] == "bullet":
                    bullets.append(item["text"])
                elif len(item["text"].split()) >= 8:
                    fallback.append(item["text"])
    return bullets or fallback


def analyze(resume: str, jd: str = "", meta: dict | None = None) -> dict:
    """Score a resume against an (optional) job description and return a full report."""
    meta = meta or {}
    lang = detect_language(resume)
    doc = parse_resume(resume)
    section_keys = {s["key"] for s in doc["sections"]}
    bullets = _collect_bullets(doc)
    words = _word_count(resume)
    risks: list[dict] = []
    breakdown: list[dict] = []

    # 1. keyword match
    keywords = {"matched": [], "missing": [], "skills_missing": []}
    if jd.strip():
        jd_lang = detect_language(jd)
        kws = extract_keywords(jd, jd_lang)
        total = sum(k["weight"] for k in kws) or 1
        got = 0
        for k in kws:
            shown = display_term(k["term"])
            if _contains(resume, k["term"]):
                got += k["weight"]
                keywords["matched"].append(shown)
            else:
                keywords["missing"].append(shown)
                if k["kind"] == "skill":
                    keywords["skills_missing"].append(shown)
        match_ratio = got / total
        breakdown.append({"key": "keywords", "score": round(40 * min(1.0, match_ratio / 0.85)), "max": 40})
        keywords["match_percent"] = round(match_ratio * 100)
        if match_ratio < 0.5:
            risks.append({"code": "risk_low_keyword_match", "severity": "high",
                          "params": {"percent": keywords["match_percent"]}})

    # 2. section completeness
    has_contact = bool(EMAIL_RE.search(resume) or PHONE_RE.search(resume))
    present = [has_contact] + [k in section_keys for k in CORE_SECTIONS]
    breakdown.append({"key": "sections", "score": 3 * sum(present), "max": 15})
    if not EMAIL_RE.search(resume):
        risks.append({"code": "risk_no_email", "severity": "high", "params": {}})
    if not PHONE_RE.search(resume):
        risks.append({"code": "risk_no_phone", "severity": "medium", "params": {}})
    for key, sev in (("experience", "high"), ("education", "medium"), ("skills", "medium"), ("summary", "low")):
        if key not in section_keys:
            risks.append({"code": "risk_missing_section", "severity": sev, "params": {"section": key}})

    # 3. formatting / parseability
    fmt_risks: list[dict] = []
    if meta.get("tables"):
        fmt_risks.append({"code": "risk_tables", "severity": "medium", "params": {"count": meta["tables"]}})
    if meta.get("images"):
        fmt_risks.append({"code": "risk_images", "severity": "low", "params": {"count": meta["images"]}})
    if meta.get("header_footer_text"):
        fmt_risks.append({"code": "risk_header_footer", "severity": "medium", "params": {}})
    if (meta.get("pages") or 0) > 2:
        fmt_risks.append({"code": "risk_too_many_pages", "severity": "low", "params": {"pages": meta["pages"]}})
    if len(SPECIAL_SYMBOL_RE.findall(resume)) >= 3:
        fmt_risks.append({"code": "risk_special_chars", "severity": "low", "params": {}})
    long_paras = [l for l in resume.split("\n") if len(l.split()) > 60]
    if long_paras:
        fmt_risks.append({"code": "risk_long_paragraphs", "severity": "low", "params": {"count": len(long_paras)}})
    if not YEAR_RE.search(resume):
        fmt_risks.append({"code": "risk_no_dates", "severity": "medium", "params": {}})
    if "experience" in section_keys and len(bullets) < 3:
        fmt_risks.append({"code": "risk_few_bullets", "severity": "medium", "params": {}})
    penalty = sum({"high": 5, "medium": 3, "low": 1}[r["severity"]] for r in fmt_risks)
    breakdown.append({"key": "formatting", "score": max(0, 15 - penalty), "max": 15})
    risks.extend(fmt_risks)

    # 4. measurable impact
    quantified = [b for b in bullets if NUMBER_RE.search(b)]
    q_ratio = len(quantified) / len(bullets) if bullets else 0
    breakdown.append({"key": "impact", "score": round(10 * min(1.0, q_ratio / 0.5)), "max": 10})

    # 5. action verbs (only languages with verb lists)
    weak_points = []
    if lang in ACTION_VERBS:
        strong = [b for b in bullets if _starts_with_action_verb(b, lang)]
        v_ratio = len(strong) / len(bullets) if bullets else 0
        breakdown.append({"key": "verbs", "score": round(10 * min(1.0, v_ratio / 0.7)), "max": 10})
    for b in bullets:
        issues = []
        if lang == "en" and any(p.search(b) for p, _ in WEAK_PATTERNS):
            issues.append("weak_verb")
        elif lang in ACTION_VERBS and not _starts_with_action_verb(b, lang):
            issues.append("no_action_verb")
        if not NUMBER_RE.search(b):
            issues.append("no_metric")
        if len(b.split()) > 40:
            issues.append("too_long")
        elif len(b.split()) < 5 and lang not in ("zh",):
            issues.append("too_short")
        if lang == "en" and re.search(r"\b(I|my|me)\b", b):
            issues.append("first_person")
        if issues:
            weak_points.append({"text": b, "issues": issues})
    if lang == "en" and len(re.findall(r"\b(I|my|me)\b", resume)) >= 3:
        risks.append({"code": "risk_first_person", "severity": "low", "params": {}})

    # 6. length
    if 400 <= words <= 900:
        length_score = 10
    elif 250 <= words < 400 or 900 < words <= 1200:
        length_score = 6
    else:
        length_score = 3
    if words < 250:
        risks.append({"code": "risk_too_short", "severity": "medium", "params": {"words": words}})
    elif words > 1200:
        risks.append({"code": "risk_too_long", "severity": "low", "params": {"words": words}})
    breakdown.append({"key": "length", "score": length_score, "max": 10})

    total_score = sum(b["score"] for b in breakdown)
    total_max = sum(b["max"] for b in breakdown)
    severity_order = {"high": 0, "medium": 1, "low": 2}
    risks.sort(key=lambda r: severity_order[r["severity"]])
    return {
        "score": round(100 * total_score / total_max),
        "language": lang,
        "has_job_description": bool(jd.strip()),
        "breakdown": breakdown,
        "keywords": keywords,
        "risks": risks,
        "weak_points": weak_points[:15],
        "stats": {
            "words": words,
            "bullets": len(bullets),
            "quantified": len(quantified),
            "sections": sorted(section_keys),
        },
    }
